 67→func runSessionsFix(cmd *cobra.Command, force bool) error {
 68→	// Check 1: Disconnected metadata branches
 69→	if err := checkDisconnectedMetadata(cmd, force); err != nil {
 70→		fmt.Fprintf(cmd.ErrOrStderr(), "Warning: metadata check failed: %v\n", err)
 71→	}
 72→	fmt.Fprintln(cmd.OutOrStdout())
 73→
 74→	// Check 2: Stuck sessions
 75→	ctx := cmd.Context()
 76→	// Load all session states
 77→	states, err := strategy.ListSessionStates(ctx)
 78→	if err != nil {
 79→		return fmt.Errorf("failed to list session states: %w", err)
 80→	}
 81→
 82→	if len(states) == 0 {
 83→		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
 84→		return nil
 85→	}
 86→
 87→	// Open repository to check shadow branches (uses worktree-aware helper)
 88→	repo, err := openRepository(ctx)
 89→	if err != nil {
 90→		return fmt.Errorf("failed to open repository: %w", err)
 91→	}
 92→
 93→	// Identify stuck sessions
 94→	now := time.Now()
 95→	var stuck []stuckSession
 96→
 97→	for _, state := range states {
 98→		ss := classifySession(state, repo, now)
 99→		if ss != nil {
100→			stuck = append(stuck, *ss)
101→		}
102→	}
103→
104→	if len(stuck) == 0 {
105→		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
106→		return nil
107→	}
108→
109→	// Get the current strategy for condense operations
110→	strat := GetStrategy(ctx)
111→
112→	fmt.Fprintf(cmd.OutOrStdout(), "Found %d stuck session(s):\n\n", len(stuck))
113→
114→	for _, ss := range stuck {
115→		displayStuckSession(cmd, ss)
116→
117→		if force {
118→			if ss.HasShadowBranch && ss.CheckpointCount > 0 {
119→				if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
120→					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
121→				} else {
122→					fmt.Fprintf(cmd.OutOrStdout(), "  -> Condensed session %s\n\n", ss.State.SessionID)
123→				}
124→			} else {
125→				// Discard if we can't condense
126→				if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
127→					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
128→				} else {
129→					fmt.Fprintf(cmd.OutOrStdout(), "  -> Discarded session %s\n\n", ss.State.SessionID)
130→				}
131→			}
132→			continue
133→		}
134→
135→		// Interactive: prompt for action
136→		action, err := promptSessionAction(ss)
137→		if err != nil {
138→			if errors.Is(err, huh.ErrUserAborted) {
139→				return nil
140→			}
141→			return fmt.Errorf("failed to get action: %w", err)
142→		}
143→
144→		switch action {
145→		case "condense":
146→			if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
147→				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
148→			} else {
149→				fmt.Fprintf(cmd.OutOrStdout(), "  -> Condensed session %s\n\n", ss.State.SessionID)
150→			}
151→		case "discard":
152→			if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
153→				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
154→			} else {
155→				fmt.Fprintf(cmd.OutOrStdout(), "  -> Discarded session %s\n\n", ss.State.SessionID)
156→			}
157→		case "skip":
158→			fmt.Fprintf(cmd.OutOrStdout(), "  -> Skipped\n\n")
159→		}
160→	}
161→
162→	return nil
163→}
