165→// classifySession determines if a session is stuck and returns diagnostic info.
166→// Returns nil if the session is healthy.
167→func classifySession(state *strategy.SessionState, repo *git.Repository, now time.Time) *stuckSession {
168→	// Determine shadow branch info
169→	shadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
170→	refName := plumbing.NewBranchReferenceName(shadowBranch)
171→	_, refErr := repo.Reference(refName, true)
172→	hasShadowBranch := refErr == nil
173→
174→	switch {
175→	case state.Phase.IsActive():
176→		// Active sessions are stuck if no interaction for over the staleness threshold
177→		isStale := state.LastInteractionTime == nil || now.Sub(*state.LastInteractionTime) > stalenessThreshold
178→		if !isStale {
179→			return nil
180→		}
181→
182→		var reason string
183→		if state.LastInteractionTime != nil {
184→			reason = fmt.Sprintf("active, last interaction %s ago", now.Sub(*state.LastInteractionTime).Truncate(time.Minute))
185→		} else {
186→			reason = "active, no recorded interaction time"
187→		}
188→
189→		return &stuckSession{
190→			State:             state,
191→			Reason:            reason,
192→			ShadowBranch:      shadowBranch,
193→			HasShadowBranch:   hasShadowBranch,
194→			CheckpointCount:   state.StepCount,
195→			FilesTouchedCount: len(state.FilesTouched),
196→		}
197→
198→	case state.Phase == session.PhaseEnded:
199→		// Ended sessions are stuck if they have uncondensed data
200→		if state.StepCount <= 0 || !hasShadowBranch {
201→			return nil
202→		}
203→
204→		return &stuckSession{
205→			State:             state,
206→			Reason:            "ended with uncondensed checkpoint data",
207→			ShadowBranch:      shadowBranch,
208→			HasShadowBranch:   hasShadowBranch,
209→			CheckpointCount:   state.StepCount,
210→			FilesTouchedCount: len(state.FilesTouched),
211→		}
212→
213→	default:
214→		return nil
215→	}
216→}
