271→// discardSession removes session state and cleans up the shadow branch.
272→func discardSession(ctx context.Context, ss stuckSession, _ *git.Repository, errW io.Writer) error {
273→	// Clear session state file
274→	if err := strategy.ClearSessionState(ctx, ss.State.SessionID); err != nil {
275→		return fmt.Errorf("failed to clear session state: %w", err)
276→	}
277→
278→	// Delete shadow branch if it exists and no other sessions need it
279→	if ss.HasShadowBranch {
280→		if shouldDelete, err := canDeleteShadowBranch(ctx, ss.ShadowBranch, ss.State.SessionID); err != nil {
281→			fmt.Fprintf(errW, "Warning: could not check other sessions for shadow branch: %v\n", err)
282→		} else if shouldDelete {
283→			if err := strategy.DeleteBranchCLI(ctx, ss.ShadowBranch); err != nil {
284→				// Branch already gone is not an error — keeps discard idempotent
285→				if !errors.Is(err, strategy.ErrBranchNotFound) {
286→					return fmt.Errorf("failed to delete shadow branch: %w", err)
287→				}
288→			}
289→		}
290→	}
291→
292→	return nil
293→}
