 78→// ReconcileDisconnectedMetadataBranch detects and repairs disconnected local/remote
 79→// entire/checkpoints/v1 branches. Disconnected means no common ancestor, which
 80→// only happens due to the empty-orphan bug. Diverged (shared ancestor) is normal
 81→// and handled by the push path's tree merge.
 82→//
 83→// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
 84→// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
 85→// apply cleanly.
 86→func ReconcileDisconnectedMetadataBranch(ctx context.Context, repo *git.Repository) error {
 87→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
 88→
 89→	// Check local branch
 90→	localRef, err := repo.Reference(refName, true)
 91→	if errors.Is(err, plumbing.ErrReferenceNotFound) {
 92→		return nil // No local branch — nothing to reconcile
 93→	}
 94→	if err != nil {
 95→		return fmt.Errorf("failed to check local metadata branch: %w", err)
 96→	}
 97→
 98→	// Check remote-tracking branch
 99→	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
100→	remoteRef, err := repo.Reference(remoteRefName, true)
101→	if errors.Is(err, plumbing.ErrReferenceNotFound) {
102→		return nil // No remote branch — nothing to reconcile
103→	}
104→	if err != nil {
105→		return fmt.Errorf("failed to check remote metadata branch: %w", err)
106→	}
107→
108→	localHash := localRef.Hash()
109→	remoteHash := remoteRef.Hash()
110→
111→	// Same hash — nothing to do
112→	if localHash == remoteHash {
113→		return nil
114→	}
115→
116→	// Check if disconnected using git merge-base
117→	repoPath, err := getRepoPath(repo)
118→	if err != nil {
119→		return err
120→	}
121→
122→	disconnected, err := isDisconnected(ctx, repoPath, localHash.String(), remoteHash.String())
123→	if err != nil {
124→		return fmt.Errorf("failed to check metadata branch ancestry: %w", err)
125→	}
126→	if !disconnected {
127→		// Shared ancestry (diverged or ancestor) — not our problem
128→		return nil
129→	}
130→
131→	// Disconnected — cherry-pick local commits onto remote tip
132→	fmt.Fprintln(os.Stderr, "[entire] Detected disconnected session metadata (local and remote share no common ancestor)")
133→
134→	// Collect local commits oldest-first
135→	localCommits, err := collectCommitChain(repo, localHash)
136→	if err != nil {
137→		return fmt.Errorf("failed to collect local commits: %w", err)
138→	}
139→
140→	// Filter out empty-tree commits (the orphan bug commit)
141→	var dataCommits []*object.Commit
142→	for _, c := range localCommits {
143→		tree, treeErr := c.Tree()
144→		if treeErr != nil {
145→			return fmt.Errorf("failed to read tree for commit %s: %w", c.Hash.String()[:7], treeErr)
146→		}
147→		if len(tree.Entries) > 0 {
148→			dataCommits = append(dataCommits, c)
149→		}
150→	}
151→
152→	if len(dataCommits) == 0 {
153→		// Local only had empty orphan — just point to remote
154→		ref := plumbing.NewHashReference(refName, remoteHash)
155→		if err := repo.Storer.SetReference(ref); err != nil {
156→			return fmt.Errorf("failed to reset metadata branch to remote: %w", err)
157→		}
158→		fmt.Fprintln(os.Stderr, "[entire] Done — local had no checkpoint data, reset to remote")
159→		return nil
160→	}
161→
162→	fmt.Fprintf(os.Stderr, "[entire] Cherry-picking %d local checkpoint(s) onto remote...\n", len(dataCommits))
163→
164→	newTip, err := cherryPickOnto(repo, remoteHash, dataCommits)
165→	if err != nil {
166→		return fmt.Errorf("failed to cherry-pick local commits onto remote: %w", err)
167→	}
168→
169→	// Update local branch ref
170→	ref := plumbing.NewHashReference(refName, newTip)
171→	if err := repo.Storer.SetReference(ref); err != nil {
172→		return fmt.Errorf("failed to update metadata branch: %w", err)
173→	}
174→
175→	fmt.Fprintln(os.Stderr, "[entire] Done — all local and remote checkpoints preserved")
176→	return nil
177→}
