179→// isDisconnected checks if two commits have no common ancestor using git merge-base.
180→// Returns (true, nil) if disconnected, (false, nil) if they share ancestry,
181→// or (false, error) if git merge-base failed for another reason.
182→//
183→// git merge-base exit codes:
184→//   - 0: common ancestor found (shared ancestry)
185→//   - 1: no common ancestor (disconnected)
186→//   - 128+: error (corrupt repo, invalid hash, etc.)
187→func isDisconnected(ctx context.Context, repoPath, hashA, hashB string) (bool, error) {
188→	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
189→	defer cancel()
190→	cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
191→	cmd.Dir = repoPath
192→	if err := cmd.Run(); err != nil {
193→		var exitErr *exec.ExitError
194→		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
195→			return true, nil // No common ancestor — disconnected
196→		}
197→		return false, fmt.Errorf("git merge-base failed: %w", err)
198→	}
199→	return false, nil // Shared ancestry
200→}
