202→// collectCommitChain walks from tip to root following first parent, returns oldest-first.
203→func collectCommitChain(repo *git.Repository, tip plumbing.Hash) ([]*object.Commit, error) {
204→	var chain []*object.Commit
205→	current := tip
206→
207→	reachedRoot := false
208→	for range MaxCommitTraversalDepth {
209→		commit, err := repo.CommitObject(current)
210→		if err != nil {
211→			return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
212→		}
213→		chain = append(chain, commit)
214→
215→		if len(commit.ParentHashes) == 0 {
216→			reachedRoot = true
217→			break
218→		}
219→		current = commit.ParentHashes[0]
220→	}
221→
222→	if !reachedRoot {
223→		return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
224→	}
225→
226→	// Reverse to oldest-first
227→	for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
228→		chain[i], chain[j] = chain[j], chain[i]
229→	}
230→
231→	return chain, nil
232→}
