234→// cherryPickOnto applies each commit's delta onto base, building a linear chain.
235→// For each commit, it computes the full diff from its parent (additions, modifications,
236→// and deletions), then applies that delta onto the current tip's tree.
237→func cherryPickOnto(repo *git.Repository, base plumbing.Hash, commits []*object.Commit) (plumbing.Hash, error) {
238→	currentTip := base
239→
240→	for _, commit := range commits {
241→		// Get the commit's tree entries
242→		commitTree, err := commit.Tree()
243→		if err != nil {
244→			return plumbing.ZeroHash, fmt.Errorf("failed to get tree for commit %s: %w", commit.Hash, err)
245→		}
246→
247→		commitEntries := make(map[string]object.TreeEntry)
248→		if err := checkpoint.FlattenTree(repo, commitTree, "", commitEntries); err != nil {
249→			return plumbing.ZeroHash, fmt.Errorf("failed to flatten commit tree: %w", err)
250→		}
251→
252→		// Get parent's tree entries (empty if root commit)
253→		parentEntries := make(map[string]object.TreeEntry)
254→		if len(commit.ParentHashes) > 0 {
255→			parentCommit, pErr := repo.CommitObject(commit.ParentHashes[0])
256→			if pErr != nil {
257→				return plumbing.ZeroHash, fmt.Errorf("failed to get parent commit %s: %w", commit.ParentHashes[0], pErr)
258→			}
259→			parentTree, ptErr := parentCommit.Tree()
260→			if ptErr != nil {
261→				return plumbing.ZeroHash, fmt.Errorf("failed to get parent tree for commit %s: %w", commit.ParentHashes[0], ptErr)
262→			}
263→			if err := checkpoint.FlattenTree(repo, parentTree, "", parentEntries); err != nil {
264→				return plumbing.ZeroHash, fmt.Errorf("failed to flatten parent tree for commit %s: %w", commit.ParentHashes[0], err)
265→			}
266→		}
267→
268→		// Compute full delta: additions, modifications, and deletions
269→		added := make(map[string]object.TreeEntry)
270→		for path, entry := range commitEntries {
271→			parentEntry, exists := parentEntries[path]
272→			if !exists || parentEntry.Hash != entry.Hash {
273→				added[path] = entry // New or modified
274→			}
275→		}
276→		var deleted []string
277→		for path := range parentEntries {
278→			if _, exists := commitEntries[path]; !exists {
279→				deleted = append(deleted, path) // Removed in this commit
280→			}
281→		}
282→
283→		if len(added) == 0 && len(deleted) == 0 {
284→			continue // Skip no-op commits
285→		}
286→
287→		// Get current tip's tree and apply delta
288→		tipCommit, err := repo.CommitObject(currentTip)
289→		if err != nil {
290→			return plumbing.ZeroHash, fmt.Errorf("failed to get tip commit: %w", err)
291→		}
292→		tipTree, err := tipCommit.Tree()
293→		if err != nil {
294→			return plumbing.ZeroHash, fmt.Errorf("failed to get tip tree: %w", err)
295→		}
296→
297→		mergedEntries := make(map[string]object.TreeEntry)
298→		if err := checkpoint.FlattenTree(repo, tipTree, "", mergedEntries); err != nil {
299→			return plumbing.ZeroHash, fmt.Errorf("failed to flatten tip tree: %w", err)
300→		}
301→		for path, entry := range added {
302→			mergedEntries[path] = entry
303→		}
304→		for _, path := range deleted {
305→			delete(mergedEntries, path)
306→		}
307→
308→		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, mergedEntries)
309→		if err != nil {
310→			return plumbing.ZeroHash, fmt.Errorf("failed to build merged tree: %w", err)
311→		}
312→
313→		// Create new commit on top of current tip, preserving original message/author
314→		newHash, err := createCherryPickCommit(repo, mergedTreeHash, currentTip, commit)
315→		if err != nil {
316→			return plumbing.ZeroHash, fmt.Errorf("failed to create cherry-pick commit: %w", err)
317→		}
318→
319→		currentTip = newHash
320→	}
321→
322→	return currentTip, nil
323→}
