325→// createCherryPickCommit creates a new commit on top of parent, preserving the
326→// original commit's message and author.
327→func createCherryPickCommit(repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (plumbing.Hash, error) {
328→	committerName, committerEmail := GetGitAuthorFromRepo(repo)
329→	now := time.Now()
330→
331→	commit := &object.Commit{
332→		TreeHash:     treeHash,
333→		ParentHashes: []plumbing.Hash{parent},
334→		Author:       original.Author,
335→		Committer: object.Signature{
336→			Name:  committerName,
337→			Email: committerEmail,
338→			When:  now,
339→		},
340→		Message: original.Message,
341→	}
342→
343→	obj := repo.Storer.NewEncodedObject()
344→	if err := commit.Encode(obj); err != nil {
345→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
346→	}
347→
348→	hash, err := repo.Storer.SetEncodedObject(obj)
349→	if err != nil {
350→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
351→	}
352→
353→	return hash, nil
354→}
